list_shipping_rules.code:
const response = await client.shippingRules.listShippingRules({zone_id: 5, method: 'flat_rate', handling_cost: 'without_handling', sort: 'name', order: 'asc'});
for (const rule of response.map.shipping_rules) {
    console.log(rule.id, rule.name, rule.shipping_rate.name);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

create_shipping_rule.code:
const response = await client.shippingRules.createShippingRule({
    shipping_rule: {
        name: 'Metro',
        description: 'Metro deliveries',
        shipping_class: 2,
        shipping_rate: 21,
        zones: [5],
        profile_id: 12,
    },
}, 'IMPORT-2026-11-05');
const rule = response.map.shipping_rule;
console.log(rule.id, rule.name, rule.shipping_rate.name, rule.transaction_no);

get_shipping_rule.code:
const response = await client.shippingRules.getShippingRule(31);
